export function updateDockedWindowsPositions(): void {
    const leftWindowIds = ['motion-list-window', 'motion-merge-window', 'expression-list-window', 'lipsync-window'];
    const rightWindowIds = ['parameter-window', 'parts-window'];
    const gap = 10;
    let x = 10;
    for (const id of leftWindowIds) {
      const el = document.getElementById(id) as HTMLDivElement;
      if (!el) continue;
      if (getComputedStyle(el).display === 'none') continue;
      el.style.top = '40px';
      const maxWidth = window.innerWidth - 40;
      const elWidth = Math.min(el.offsetWidth || 220, maxWidth);
      el.style.width = `${elWidth}px`;
      el.style.left = `${x}px`;
      el.style.right = '';
      x += elWidth + gap;
    }
    let rightX = 10;
    for (const id of rightWindowIds) {
      const el = document.getElementById(id) as HTMLDivElement;
      if (!el) continue;
      if (getComputedStyle(el).display === 'none') continue;
      el.style.top = '40px';
      const maxWidth = window.innerWidth - 40;
      const elWidth = Math.min(el.offsetWidth || 220, maxWidth);
      el.style.width = `${elWidth}px`;
      el.style.right = `${rightX}px`;
      el.style.left = '';
      rightX += elWidth + gap;
    }
}