import { focusRelative } from './focusable';
import { updateDockedWindowsPositions } from "./windows";
import { LAppDelegate } from '../delegation/delegate';
import * as LAppDefine from '../core/define';

export default function setupMotionListUI(): void {
    const toggleBtn = document.getElementById('toggle-window-btn') as HTMLButtonElement;
    const mergeToggleBtn = document.getElementById('toggle-merge-btn') as HTMLButtonElement;
    const windowDiv = document.getElementById('motion-list-window') as HTMLDivElement;
    const mergeWindowDiv = document.getElementById('motion-merge-window') as HTMLDivElement;
    const listUl = document.getElementById('motion-list') as HTMLUListElement;
    const multiSelect = document.getElementById('motion-multi-select') as HTMLSelectElement;
    const mergeBtn = document.getElementById('merge-btn') as HTMLButtonElement;
    const mergeRecordBtn = document.getElementById('merge-record-btn') as HTMLButtonElement;
    const clearBtn = document.getElementById('clear-selection-btn') as HTMLButtonElement;
    const selectedCount = document.getElementById('selected-motions-count') as HTMLSpanElement;
    const selectedList = document.getElementById('selected-motions-list') as HTMLDivElement;
    if (toggleBtn) toggleBtn.setAttribute('aria-controls', 'motion-list-window');
    if (toggleBtn) toggleBtn.setAttribute('aria-expanded', 'false');
    if (windowDiv) windowDiv.setAttribute('role', 'dialog');
    if (windowDiv) windowDiv.setAttribute('aria-hidden', 'true');
    if (windowDiv) windowDiv.setAttribute('tabindex', '0');
    if (mergeToggleBtn) mergeToggleBtn.setAttribute('aria-controls', 'motion-merge-window');
    if (mergeToggleBtn) mergeToggleBtn.setAttribute('aria-expanded', 'false');
    if (mergeWindowDiv) mergeWindowDiv.setAttribute('role', 'dialog');
    if (mergeWindowDiv) mergeWindowDiv.setAttribute('aria-hidden', 'true');
    if (mergeWindowDiv) mergeWindowDiv.setAttribute('tabindex', '0');
    if (windowDiv) {
        windowDiv.addEventListener('keydown', (e) => {
            const active = document.activeElement as HTMLElement | null;
            if (e.key === 'ArrowDown') {
                e.preventDefault();
                focusRelative(windowDiv, active, 'next');
            } else if (e.key === 'ArrowUp') {
                e.preventDefault();
                focusRelative(windowDiv, active, 'prev');
            } else if (e.key === 'Enter') {
                if (active && active.tagName === 'BUTTON') {
                    (active as HTMLButtonElement).click();
                }
            }
        });
    }
    if (!toggleBtn || !windowDiv || !listUl) {
        console.error('Motion List UI elements not found in HTML.');
        return;
    }
    if (!mergeToggleBtn || !mergeWindowDiv || !multiSelect || !mergeBtn || !mergeRecordBtn || !clearBtn || !selectedCount || !selectedList) {
        console.error('Motion Merge UI elements not found in HTML.');
        return;
    }
    let isWindowVisible = false;
    let isMergeWindowVisible = false;
    toggleBtn.addEventListener('click', () => {
        isWindowVisible = !isWindowVisible;
        windowDiv.style.display = isWindowVisible ? 'block' : 'none';
        toggleBtn.setAttribute('aria-expanded', String(isWindowVisible));
        windowDiv.setAttribute('aria-hidden', String(!isWindowVisible));
        updateMotionList();
        updateDockedWindowsPositions();
        if (isWindowVisible) {
            const focusTarget = (listUl.querySelector('button') as HTMLElement | null) ?? windowDiv;
            focusTarget?.focus();
        } else {
            toggleBtn.focus();
        }
    });
    mergeToggleBtn.addEventListener('click', () => {
        isMergeWindowVisible = !isMergeWindowVisible;
        mergeWindowDiv.style.display = isMergeWindowVisible ? 'block' : 'none';
        mergeToggleBtn.setAttribute('aria-expanded', String(isMergeWindowVisible));
        mergeWindowDiv.setAttribute('aria-hidden', String(!isMergeWindowVisible));
        updateMotionList();
        updateDockedWindowsPositions();
        if (isMergeWindowVisible) {
            multiSelect.focus();
        } else {
            mergeToggleBtn.focus();
        }
    });
    updateDockedWindowsPositions();
    mergeBtn.disabled = true;
    mergeBtn.title = 'Select two or more motions to enable merging';
    mergeRecordBtn.disabled = true;
    mergeRecordBtn.title = 'Select two or more motions to enable merging/recording';
    mergeBtn.addEventListener('click', async () => {
        const appDelegate = LAppDelegate.getInstance();
        const subdelegates = appDelegate.getSubdelegates();
        if (!subdelegates || subdelegates.getSize() === 0) {
            console.error('[MotionListUI] No subdelegates found for merge.');
            return;
        }
        const firstSubdelegate = subdelegates.at(0);
        if (!firstSubdelegate) {
            console.error('[MotionListUI] No first subdelegate found for merge.');
            return;
        }
        const live2DManager = firstSubdelegate.getLive2DManager();
        if (!live2DManager) {
            console.error(
                '[MotionListUI] No Live2DManager found in subdelegate for merge.'
            );
            return;
        }
        const currentModel = live2DManager.getCurrentModel();
        if (!currentModel) {
            console.error(
                '[MotionListUI] No current model found in manager for merge.'
            );
            return;
        }
        const selectedNames: string[] = [];
        for (let i = 0; i < multiSelect.options.length; i++) {
            if (multiSelect.options[i].selected) {
                selectedNames.push(multiSelect.options[i].value);
            }
        }
        if (selectedNames.length < 2) {
            console.warn(
                '[MotionListUI] Please select at least two motions to merge.'
            );
            alert('Please select at least two motions to merge.');
            return;
        }
        
        try {
            const success = await currentModel.startMergedMotionFromNamesArray(
                selectedNames,
                LAppDefine.PriorityForce
            );
            if (success) {
            } else {
                console.error('[MotionListUI] Failed to start merged motion.');
                alert('Failed to start merged motion. Check console for details.');
            }
        } catch (error) {
            console.error('[MotionListUI] Error during merge process:', error);
            alert(
                'An error occurred during the merge process. Check console for details.'
            );
        }
    });
    mergeRecordBtn.addEventListener('click', async () => {
        const appDelegate = LAppDelegate.getInstance();
        const subdelegates = appDelegate.getSubdelegates();
        if (!subdelegates || subdelegates.getSize() === 0) {
            console.error('[MotionListUI] No subdelegates found for merge+record.');
            return;
        }
        const firstSubdelegate = subdelegates.at(0);
        if (!firstSubdelegate) {
            console.error('[MotionListUI] No first subdelegate found for merge+record.');
            return;
        }
        const live2DManager = firstSubdelegate.getLive2DManager();
        if (!live2DManager) {
            console.error(
                '[MotionListUI] No Live2DManager found in subdelegate for merge+record.'
            );
            return;
        }
        const currentModel = live2DManager.getCurrentModel();
        if (!currentModel) {
            console.error(
                '[MotionListUI] No current model found in manager for merge+record.'
            );
            return;
        }
        const selectedNames: string[] = [];
        for (let i = 0; i < multiSelect.options.length; i++) {
            if (multiSelect.options[i].selected) {
                selectedNames.push(multiSelect.options[i].value);
            }
        }
        if (selectedNames.length < 2) {
            console.warn(
                '[MotionListUI] Please select at least two motions to merge+record.'
            );
            alert('Please select at least two motions to merge & record.');
            return;
        }
        
        try {
            const startAuto = (window as any).startAutoRecording as
                | (() => Promise<void>)
                | undefined;
            const stopAuto = (window as any).stopAutoRecording as
                | (() => void)
                | undefined;
            const onBegan = async () => {
                if (!startAuto) return;
                try {
                    await startAuto();
                } catch (e) {
                    console.warn('[MotionListUI] startAutoRecording failed (merge+record):', e);
                }
            };
            const onFinished = () => {
                if (!stopAuto) return;
                try {
                    stopAuto();
                } catch (e) {
                    console.warn('[MotionListUI] stopAutoRecording failed (merge+record):', e);
                }
            };
            const success = await currentModel.startMergedMotionFromNamesArray(
                selectedNames,
                LAppDefine.PriorityForce,
                onFinished as any,
                onBegan as any
            );
            if (success) {
            } else {
                console.error('[MotionListUI] Failed to start merged motion (recorded).');
                alert('Failed to start merged motion. Check console for details.');
            }
        } catch (error) {
            console.error('[MotionListUI] Error during merge+record process:', error);
            alert(
                'An error occurred during the merge+record process. Check console for details.'
            );
        }
    });
    multiSelect.addEventListener('change', () => {
        const selectedOptions = Array.from(multiSelect.options).filter(o => o.selected);
        const selectedCountValue = selectedOptions.length;
        const hasEnough = selectedCountValue >= 2;
        mergeBtn.disabled = !hasEnough;
        mergeRecordBtn.disabled = !hasEnough;
        mergeBtn.textContent = selectedCountValue > 0 ? `Merge & Play (${selectedCountValue})` : 'Merge & Play';
        mergeRecordBtn.textContent = selectedCountValue > 0 ? `Merge & Record (${selectedCountValue})` : 'Merge & Record';
        selectedCount.textContent = selectedCountValue.toString();
        selectedList.innerHTML = '';
        selectedOptions.forEach(option => {
            const item = document.createElement('div');
            item.className = 'selected-list-item';
            item.textContent = option.textContent;
            selectedList.appendChild(item);
        });
    });
    clearBtn.addEventListener('click', () => {
        multiSelect.selectedIndex = -1;
        selectedCount.textContent = '0';
        selectedList.innerHTML = '';
        mergeBtn.disabled = true;
        mergeBtn.textContent = 'Merge & Play';
        mergeRecordBtn.disabled = true;
        mergeRecordBtn.textContent = 'Merge & Record';
    });
    mergeBtn.textContent = 'Merge & Play';
    mergeRecordBtn.textContent = 'Merge & Record';
    function updateMotionList(): void {
        listUl.innerHTML = '';
        multiSelect.innerHTML = '';
        const appDelegate = LAppDelegate.getInstance();
        const subdelegates = appDelegate.getSubdelegates();
        if (!subdelegates || subdelegates.getSize() === 0) {
            console.error('[MotionListUI] No subdelegates found in appDelegate.');
            const listItem = document.createElement('li');
            const span = document.createElement('span');
            span.textContent = 'No subdelegates found';
            listItem.appendChild(span);
            listUl.appendChild(listItem);
            return;
        }
        const firstSubdelegate = subdelegates.at(0);
        if (!firstSubdelegate) {
            console.error('[MotionListUI] No first subdelegate found.');
            const listItem = document.createElement('li');
            const span = document.createElement('span');
            span.textContent = 'No first subdelegate found';
            listItem.appendChild(span);
            listUl.appendChild(listItem);
            return;
        }
        const live2DManager = firstSubdelegate.getLive2DManager();
        if (!live2DManager) {
            console.error('[MotionListUI] No Live2DManager found in subdelegate.');
            const listItem = document.createElement('li');
            const span = document.createElement('span');
            span.textContent = 'No Live2DManager found in subdelegate';
            listItem.appendChild(span);
            listUl.appendChild(listItem);
            return;
        }
        const currentModel = live2DManager.getCurrentModel();
        if (currentModel) {
            
            const motionNames = live2DManager.getCurrentModelLoadedMotionNames();
            
            if (motionNames.length === 0) {
                const listItem = document.createElement('li');
                const span = document.createElement('span');
                span.textContent = 'Motions not loaded yet or empty (in callback)';
                listItem.appendChild(span);
                listUl.appendChild(listItem);
                console.warn('[MotionListUI] Motion names array is empty in callback.');
                return;
            }
            motionNames.forEach((name: string) => {
                const option = document.createElement('option');
                option.value = name;
                option.textContent = name;
                multiSelect.appendChild(option);
            });
            mergeBtn.disabled = motionNames.length < 2;
            mergeBtn.textContent = 'Merge & Play';
            if (motionNames.length < 2) mergeBtn.title = 'Select two or more motions to enable merging';
            else mergeBtn.title = '';
            motionNames.forEach((name: string) => {
                const listItem = document.createElement('li');
                const playButton = document.createElement('button');
                playButton.className = 'motion-btn';
                playButton.textContent = name;
                const recordButton = document.createElement('button');
                recordButton.textContent = 'REC';
                recordButton.title = 'Record ONLY this motion to video';
                recordButton.style.marginLeft = '6px';
                recordButton.style.padding = '6px 8px';
                recordButton.style.fontSize = '0.7em';
                recordButton.style.borderRadius = '6px';
                recordButton.style.border = '1px solid rgba(255,255,255,0.25)';
                recordButton.style.background = 'rgba(255,80,80,0.2)';
                recordButton.style.color = '#ffdede';
                recordButton.style.cursor = 'pointer';
                playButton.addEventListener('click', () => {
                    updateDockedWindowsPositions();
                    const lastUnderscore = name.lastIndexOf('_');
                    if (lastUnderscore !== -1) {
                        const group = name.substring(0, lastUnderscore);
                        const no = parseInt(name.substring(lastUnderscore + 1));
                        currentModel.startMotion(group, no, LAppDefine.PriorityForce);
                    } else {
                        console.warn(`[MotionListUI] Could not parse motion name: ${name}`);
                        currentModel.startMotionByName(name, LAppDefine.PriorityForce);
                    }
                });
                recordButton.addEventListener('click', () => {
                    
                    updateDockedWindowsPositions();
                    const startAuto = (window as any).startAutoRecording as
                        | (() => Promise<void>)
                        | undefined;
                    const stopAuto = (window as any).stopAutoRecording as
                        | (() => void)
                        | undefined;
                    if (!startAuto || !stopAuto) {
                        alert(
                            'Recording controls are not ready yet. Please wait for the page to finish loading.'
                        );
                        return;
                    }
                    const lastUnderscore = name.lastIndexOf('_');
                    if (lastUnderscore !== -1) {
                        const group = name.substring(0, lastUnderscore);
                        const no = parseInt(name.substring(lastUnderscore + 1));
                        const onFinished = () => {
                            try {
                                stopAuto();
                            } catch (e) {
                                console.warn('[MotionListUI] stopAutoRecording failed:', e);
                            }
                        };
                        const onBegan = async () => {
                            try {
                                await startAuto();
                            } catch (e) {
                                console.warn('[MotionListUI] startAutoRecording failed:', e);
                            }
                        };
                        currentModel.startMotion(
                            group,
                            no,
                            LAppDefine.PriorityForce,
                            onFinished as any,
                            onBegan as any
                        );
                    } else {
                        console.warn(
                            `[MotionListUI] Could not parse motion name for REC: ${name}`
                        );
                        alert(
                            'This motion name cannot be parsed into a group/index, so motion-locked recording is not available for it.'
                        );
                    }
                });
                listItem.appendChild(playButton);
                listItem.appendChild(recordButton);
                listUl.appendChild(listItem);
            });
            
            try {
                const view = firstSubdelegate.getView();
                if (view && (view as any).captureInitialViewState) {
                    (view as any).captureInitialViewState();
                }
            } catch (e) {
                console.warn('[MotionListUI] Failed to capture initial view state', e);
            }
            if ((window as any).updateExpressionList) (window as any).updateExpressionList();
            if ((window as any).updateParameterList) (window as any).updateParameterList();
            if ((window as any).updateLipSyncTargets) (window as any).updateLipSyncTargets();
            updateDockedWindowsPositions();
        } else {
            console.warn(
                '[MotionListUI] No current model found in manager (in callback).'
            );
            const listItem = document.createElement('li');
            const span = document.createElement('span');
            span.textContent = 'No model loaded (in callback)';
            listItem.appendChild(span);
            listUl.appendChild(listItem);
        }
    }
    const appDelegate = LAppDelegate.getInstance();
    appDelegate.setUpdateMotionListCallback(() => {
        updateMotionList();
        if ((window as any).updatePartsList) {
            (window as any).updatePartsList();
        }
        if ((window as any).updateWorkspaceList) {
            (window as any).updateWorkspaceList();
        }
    });
}

export function resetMergeSelection(): void {
    const multiSelect = document.getElementById('motion-multi-select') as HTMLSelectElement;
    const selectedCount = document.getElementById('selected-motions-count') as HTMLSpanElement;
    const selectedList = document.getElementById('selected-motions-list') as HTMLDivElement;
    const mergeBtn = document.getElementById('merge-btn') as HTMLButtonElement;
    if (multiSelect) {
        multiSelect.selectedIndex = -1;
    }
    if (selectedCount) {
        selectedCount.textContent = '0';
    }
    if (selectedList) {
        selectedList.innerHTML = '';
    }
    if (mergeBtn) {
        mergeBtn.disabled = true;
        mergeBtn.textContent = 'Merge & Play';
    }
}