import { LAppDelegate } from "../delegation/delegate";

export type BackgroundMode = 'solid' | 'gradient' | 'image';
export interface BackgroundState {
  mode: BackgroundMode;
  solidColor: string;
  gradientStart: string;
  gradientEnd: string;
  gradientAngle: number;
  imageDataUrl: string | null;
}

export const getPrimaryView = () => {
    const appDelegate = LAppDelegate.getInstance();
    const subs = appDelegate.getSubdelegates();
    if (!subs || subs.getSize() === 0) return null;
    const sub = subs.at(0);
    return sub ? sub.getView() : null;
};

export const hexToRgb = (hex: string): { r: number; g: number; b: number } => {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result
        ? {
            r: parseInt(result[1], 16) / 255,
            g: parseInt(result[2], 16) / 255,
            b: parseInt(result[3], 16) / 255,
        }
        : { r: 1.0, g: 1.0, b: 1.0 };
};

export const mixHexColors = (c1: string, c2: string): string => {
    const n1 = hexToRgb(c1);
    const n2 = hexToRgb(c2);
    const to255 = (v: number) => Math.round(Math.min(Math.max(v, 0), 1) * 255);
    const r = to255((n1.r + n2.r) / 2);
    const g = to255((n1.g + n2.g) / 2);
    const b = to255((n1.b + n2.b) / 2);
    const toHex = (v: number) => v.toString(16).padStart(2, '0');
    return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
};

export const applyBackgroundState = (state: BackgroundState) => {
    const gradPreview = document.getElementById('bg-grad-preview') as HTMLDivElement | null;
    const imagePreview = document.getElementById('bg-image-preview') as HTMLDivElement | null;
    const bgBtn = document.getElementById('btn-bg-picker') as HTMLButtonElement | null;
    
    let effectiveColorForClear: string | null = null;
    if (state.mode === 'solid') {
        document.body.style.backgroundImage = '';
        document.body.style.backgroundColor = state.solidColor;
        const canvases = document.querySelectorAll('canvas');
        canvases.forEach((canvas) => {
            const el = (canvas as HTMLCanvasElement);
            el.style.position = 'absolute';
            el.style.left = '0';
            el.style.top = '0';
            el.style.zIndex = '50';
            el.style.backgroundImage = '';
            el.style.backgroundColor = state.solidColor;
        });
        effectiveColorForClear = state.solidColor;
    } else if (state.mode === 'gradient') {
        const gradientCss = `linear-gradient(${state.gradientAngle}deg, ${state.gradientStart}, ${state.gradientEnd})`;
        document.body.style.backgroundImage = gradientCss;
        document.body.style.backgroundColor = 'transparent';
        const canvases = document.querySelectorAll('canvas');
        canvases.forEach((canvas) => {
            const el = (canvas as HTMLCanvasElement);
            el.style.position = 'absolute';
            el.style.left = '0';
            el.style.top = '0';
            el.style.zIndex = '50';
            el.style.backgroundImage = gradientCss;
            el.style.backgroundColor = 'transparent';
        });
        effectiveColorForClear = mixHexColors(state.gradientStart, state.gradientEnd);
    } else if (state.mode === 'image') {
        document.body.style.backgroundColor = '#000000';
        if (state.imageDataUrl) {
            document.body.style.backgroundImage = `url(${state.imageDataUrl})`;
            document.body.style.backgroundSize = 'cover';
            document.body.style.backgroundPosition = 'center center';
        } else {
            document.body.style.backgroundImage = '';
        }
        const canvases = document.querySelectorAll('canvas');
        canvases.forEach((canvas) => {
            const el = (canvas as HTMLCanvasElement);
            el.style.position = 'absolute';
            el.style.left = '0';
            el.style.top = '0';
            el.style.zIndex = '50';
            el.style.backgroundImage = '';
            el.style.backgroundColor = 'transparent';
        });
        effectiveColorForClear = state.solidColor || '#000000';
    }
    if (gradPreview) {
        const gradCss = `linear-gradient(${state.gradientAngle}deg, ${state.gradientStart}, ${state.gradientEnd})`;
        gradPreview.style.backgroundImage = gradCss;
    }
    if (imagePreview) {
        if (state.imageDataUrl) {
            imagePreview.style.backgroundImage = `url(${state.imageDataUrl})`;
        } else {
            imagePreview.style.backgroundImage = '';
        }
    }
    if (bgBtn) {
        const swatch = bgBtn.querySelector('.bg-swatch') as HTMLElement | null;
        if (swatch) {
            if (state.mode === 'solid') {
                swatch.style.background = state.solidColor;
            } else if (state.mode === 'gradient') {
                swatch.style.backgroundImage = `linear-gradient(${state.gradientAngle}deg, ${state.gradientStart}, ${state.gradientEnd})`;
            } else if (state.mode === 'image') {
                swatch.style.backgroundImage = state.imageDataUrl
                    ? `url(${state.imageDataUrl})`
                    : 'linear-gradient(135deg, #222, #555)';
            }
        }
    }
    if (effectiveColorForClear) {
        const rgb = hexToRgb(effectiveColorForClear);
        (window as any).live2dClearColor = rgb;
        try {
            const canvases = document.querySelectorAll('canvas');
            canvases.forEach((canvas) => {
                const gl =
                    canvas.getContext('webgl') ||
                    canvas.getContext('webgl2') ||
                    canvas.getContext('experimental-webgl');
                if (gl) {
                    (gl as WebGLRenderingContext).clearColor(rgb.r, rgb.g, rgb.b, 1.0);
                }
            });
        } catch (e) {
        }
    }
    const view = getPrimaryView();
    if (view && (view as any).setBackgroundTextureFromUrl) {
        if (state.mode === 'solid') {
            (view as any).setBackgroundTextureFromUrl(null);
        } else if (state.mode === 'gradient') {
            const size = 512;
            const canvas = document.createElement('canvas');
            canvas.width = size;
            canvas.height = size;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                const angleRad = (state.gradientAngle * Math.PI) / 180;
                const half = size / 2;
                const dx = Math.cos(angleRad) * half;
                const dy = Math.sin(angleRad) * half;
                const x0 = half - dx;
                const y0 = half - dy;
                const x1 = half + dx;
                const y1 = half + dy;
                const grad = ctx.createLinearGradient(x0, y0, x1, y1);
                grad.addColorStop(0, state.gradientStart);
                grad.addColorStop(1, state.gradientEnd);
                ctx.fillStyle = grad;
                ctx.fillRect(0, 0, size, size);
                const url = canvas.toDataURL('image/png');
                (view as any).setBackgroundTextureFromUrl(url);
            }
        } else if (state.mode === 'image') {
            (view as any).setBackgroundTextureFromUrl(state.imageDataUrl || null);
        }
    }
};

export function saveBackgroundState(state: BackgroundState): void {
  try {
    localStorage.setItem('app_bg_state', JSON.stringify(state));
  } catch (e) {
    console.warn('Failed to save background state:', e);
  }
}

export function loadBackgroundState(defaultColor: string): BackgroundState {
    try {
      const raw = localStorage.getItem('app_bg_state');
      if (raw) {
        const parsed = JSON.parse(raw) as Partial<BackgroundState>;
        return {
          mode: (parsed.mode as BackgroundMode) || 'solid',
          solidColor: parsed.solidColor || defaultColor,
          gradientStart: parsed.gradientStart || defaultColor,
          gradientEnd: parsed.gradientEnd || defaultColor,
          gradientAngle: typeof parsed.gradientAngle === 'number' ? parsed.gradientAngle : 45,
          imageDataUrl: parsed.imageDataUrl || null,
        };
      }
    } catch (e) {
      console.warn('Failed to load background state:', e);
    }
    return {
      mode: 'solid',
      solidColor: defaultColor,
      gradientStart: defaultColor,
      gradientEnd: defaultColor,
      gradientAngle: 45,
      imageDataUrl: null,
    };
  }
