import { updateDockedWindowsPositions } from "./windows";
import { LAppDelegate } from '../delegation/delegate';

export function setupPartsUI(): void {
    const toggleBtn = document.getElementById('toggle-parts-btn') as HTMLButtonElement;
    const windowDiv = document.getElementById('parts-window') as HTMLDivElement;
    const partsList = document.getElementById('parts-list') as HTMLDivElement;
    if (!toggleBtn || !windowDiv || !partsList) {
        console.error('Parts UI elements not found in HTML.');
        return;
    }
    let isWindowVisible = false;
    toggleBtn.setAttribute('aria-controls', 'parts-window');
    toggleBtn.setAttribute('aria-expanded', 'false');
    windowDiv.setAttribute('role', 'dialog');
    windowDiv.setAttribute('aria-hidden', 'true');
    windowDiv.setAttribute('tabindex', '0');
    toggleBtn.addEventListener('click', () => {
        isWindowVisible = !isWindowVisible;
        windowDiv.style.display = isWindowVisible ? 'block' : 'none';
        toggleBtn.setAttribute('aria-expanded', String(isWindowVisible));
        windowDiv.setAttribute('aria-hidden', String(!isWindowVisible));
        if (isWindowVisible) {
            updatePartsList();
            const focusTarget = partsList.querySelector('button') as HTMLElement | null;
            if (focusTarget) focusTarget.focus();
        } else {
            toggleBtn.focus();
        }
        updateDockedWindowsPositions();
    });
    function updatePartsList(): void {
        partsList.innerHTML = '';
        const appDelegate = LAppDelegate.getInstance();
        const subdelegates = appDelegate.getSubdelegates();
        if (!subdelegates || subdelegates.getSize() === 0) {
            console.error('[PartsUI] No subdelegates found.');
            const messageDiv = document.createElement('div');
            messageDiv.textContent = 'No model loaded';
            messageDiv.style.color = '#aaa';
            messageDiv.style.textAlign = 'center';
            messageDiv.style.padding = '20px';
            partsList.appendChild(messageDiv);
            return;
        }
        const firstSubdelegate = subdelegates.at(0);
        if (!firstSubdelegate) {
            console.error('[PartsUI] No first subdelegate found.');
            const messageDiv = document.createElement('div');
            messageDiv.textContent = 'No model loaded';
            messageDiv.style.color = '#aaa';
            messageDiv.style.textAlign = 'center';
            messageDiv.style.padding = '20px';
            partsList.appendChild(messageDiv);
            return;
        }
        const live2DManager = firstSubdelegate.getLive2DManager();
        if (!live2DManager) {
            console.error('[PartsUI] No Live2DManager found.');
            const messageDiv = document.createElement('div');
            messageDiv.textContent = 'No model loaded';
            messageDiv.style.color = '#aaa';
            messageDiv.style.textAlign = 'center';
            messageDiv.style.padding = '20px';
            partsList.appendChild(messageDiv);
            return;
        }
        const currentModel = live2DManager.getCurrentModel();
        if (!currentModel) {
            console.warn('[PartsUI] No current model found.');
            const messageDiv = document.createElement('div');
            messageDiv.textContent = 'No model loaded';
            messageDiv.style.color = '#aaa';
            messageDiv.style.textAlign = 'center';
            messageDiv.style.padding = '20px';
            partsList.appendChild(messageDiv);
            return;
        }
        const model = currentModel.getModel();
        if (!model) {
            console.error('[PartsUI] Model not accessible via getModel().');
            const messageDiv = document.createElement('div');
            messageDiv.textContent = 'Model not accessible';
            messageDiv.style.color = '#aaa';
            messageDiv.style.textAlign = 'center';
            messageDiv.style.padding = '20px';
            partsList.appendChild(messageDiv);
            return;
        }
        const coreModel = (model as any)._model || (model as any)._ptr || (model as any);
        if (!coreModel) {
            console.error('[PartsUI] Core model not accessible.');
            const messageDiv = document.createElement('div');
            messageDiv.textContent = 'Core model not accessible';
            messageDiv.style.color = '#aaa';
            messageDiv.style.textAlign = 'center';
            messageDiv.style.padding = '20px';
            partsList.appendChild(messageDiv);
            return;
        }
        const partOpacities = (model as any)._partOpacities;
        const partIds = (model as any)._partIds;
        const coreModelParts = (coreModel as any).parts;
        if (!partOpacities || !partIds) {
            console.error('[PartsUI] Part arrays not available.');
            const messageDiv = document.createElement('div');
            messageDiv.textContent = 'Part arrays not available';
            messageDiv.style.color = '#aaa';
            messageDiv.style.textAlign = 'center';
            messageDiv.style.padding = '20px';
            partsList.appendChild(messageDiv);
            return;
        }
        const partCount = partOpacities.length;
        if (partCount === 0) {
            const messageDiv = document.createElement('div');
            messageDiv.textContent = 'No parts found';
            messageDiv.style.color = '#aaa';
            messageDiv.style.textAlign = 'center';
            messageDiv.style.padding = '20px';
            partsList.appendChild(messageDiv);
            return;
        }
        const partElements = new Map<number, { toggle: HTMLElement, label: string }>();
        for (let i = 0; i < partCount; i++) {
            const partIndex = i;
            let partId = `Part_${partIndex}`;
            try {
                if (partIds && partIds._ptr && partIds._ptr[i]) {
                    const idHandle = partIds._ptr[i];
                    if (idHandle && idHandle._id && idHandle._id.s) {
                        partId = idHandle._id.s;
                    }
                }
            } catch (e) {
                console.warn(`[PartsUI] Could not get part ID for index ${partIndex}:`, e);
            }
            let currentOpacity = 0;
            try {
                currentOpacity = partOpacities[i] || 0;
            } catch (e) {
                console.warn(`[PartsUI] Could not get opacity for part ${partId}:`, e);
            }
            const isVisible = currentOpacity > 0.01;
            const partItem = document.createElement('div');
            partItem.className = 'part-item';
            const label = document.createElement('span');
            label.className = 'part-label';
            label.textContent = `${partId} [${partIndex}]`;
            const toggle = document.createElement('div');
            toggle.className = `part-toggle ${isVisible ? 'active' : ''}`;
            toggle.setAttribute('role', 'switch');
            toggle.setAttribute('aria-checked', String(isVisible));
            toggle.setAttribute('aria-label', `Toggle ${partId} visibility`);
            const slider = document.createElement('div');
            slider.className = 'part-toggle-slider';
            toggle.appendChild(slider);
            partElements.set(partIndex, { toggle, label: partId });
            toggle.addEventListener('click', () => {
                const currentOpacity = partOpacities[i] || 0;
                const currentlyVisible = currentOpacity > 0.01;
                const newOpacity = currentlyVisible ? 0 : 1;
                try {
                    partOpacities[i] = newOpacity;
                } catch (e) {
                    console.error(`[PartsUI] Failed to set opacity for ${partId}:`, e);
                }
                toggle.classList.toggle('active', newOpacity > 0.01);
                toggle.setAttribute('aria-checked', String(newOpacity > 0.01));
            });
            partItem.appendChild(label);
            partItem.appendChild(toggle);
            partsList.appendChild(partItem);
        }
        const resetBtn = document.getElementById('parts-reset-btn') as HTMLButtonElement;
        if (resetBtn) {
            resetBtn.addEventListener('click', () => {
                partElements.forEach((elements, index) => {
                    try {
                        partOpacities[index] = 1;
                        elements.toggle.classList.add('active');
                        elements.toggle.setAttribute('aria-checked', 'true');
                    } catch (e) {
                        console.error(`[PartsUI] Failed to reset part ${elements.label}:`, e);
                    }
                });
            });
        }
    }
    (window as any).updatePartsList = updatePartsList;
}