import { LAppDelegate } from "../delegation/delegate";
import { updateDockedWindowsPositions } from "./windows";
import { setUIElementActive } from "./state";

export function setupLipSyncUI(): void {
    const toggleBtn = document.getElementById('toggle-lipsync-btn') as HTMLButtonElement | null;
    const windowDiv = document.getElementById('lipsync-window') as HTMLDivElement | null;
    const enableCheckbox = document.getElementById('lipsync-enable') as HTMLInputElement | null;
    const statusEl = document.getElementById('lipsync-status') as HTMLSpanElement | null;
    const meterFill = document.getElementById('lipsync-meter-fill') as HTMLDivElement | null;
    const sourceMic = document.getElementById('lipsync-source-mic') as HTMLInputElement | null;
    const sourceFile = document.getElementById('lipsync-source-file') as HTMLInputElement | null;
    const micControls = document.getElementById('lipsync-mic-controls') as HTMLDivElement | null;
    const micBtn = document.getElementById('lipsync-mic-btn') as HTMLButtonElement | null;
    const micStatus = document.getElementById('lipsync-mic-status') as HTMLSpanElement | null;
    const fileControls = document.getElementById('lipsync-file-controls') as HTMLDivElement | null;
    const fileInput = document.getElementById('lipsync-file-input') as HTMLInputElement | null;
    const filePlayBtn = document.getElementById('lipsync-file-play') as HTMLButtonElement | null;
    const fileStopBtn = document.getElementById('lipsync-file-stop') as HTMLButtonElement | null;
    const fileNameEl = document.getElementById('lipsync-file-name') as HTMLSpanElement | null;
    const sensitivitySlider = document.getElementById('lipsync-sensitivity') as HTMLInputElement | null;
    const smoothingSlider = document.getElementById('lipsync-smoothing') as HTMLInputElement | null;
    const gateSlider = document.getElementById('lipsync-gate') as HTMLInputElement | null;
    const sensitivityVal = document.getElementById('lipsync-sensitivity-val') as HTMLSpanElement | null;
    const smoothingVal = document.getElementById('lipsync-smoothing-val') as HTMLSpanElement | null;
    const gateVal = document.getElementById('lipsync-gate-val') as HTMLSpanElement | null;
    const targetsEl = document.getElementById('lipsync-targets') as HTMLSpanElement | null;
    const refreshBtn = document.getElementById('lipsync-refresh-btn') as HTMLButtonElement | null;
    const disableBtn = document.getElementById('lipsync-disable-btn') as HTMLButtonElement | null;
    if (!toggleBtn || !windowDiv || !enableCheckbox || !statusEl || !meterFill ||
        !sourceMic || !sourceFile || !micControls || !micBtn || !micStatus ||
        !fileControls || !fileInput || !filePlayBtn || !fileStopBtn || !fileNameEl ||
        !sensitivitySlider || !smoothingSlider || !gateSlider || !sensitivityVal ||
        !smoothingVal || !gateVal || !targetsEl || !refreshBtn || !disableBtn) {
      console.error('Lip Sync UI elements not found in HTML.');
      return;
    }
    type LipSyncSource = 'mic' | 'file';
    let isWindowVisible = false;
    let enabled = false;
    let currentSource: LipSyncSource = 'mic';
    let audioContext: AudioContext | null = null;
    let analyser: AnalyserNode | null = null;
    let analyserBuffer: Float32Array | null = null;
    let micStream: MediaStream | null = null;
    let micSource: MediaStreamAudioSourceNode | null = null;
    let fileAudio: HTMLAudioElement | null = new Audio();
    let fileSource: MediaElementAudioSourceNode | null = null;
    let fileUrl: string | null = null;
    let rafId: number | null = null;
    let smoothed = 0;
    let targetParams: Array<{ id: string; min: number; max: number }> = [];
    toggleBtn.setAttribute('aria-controls', 'lipsync-window');
    toggleBtn.setAttribute('aria-expanded', 'false');
    windowDiv.setAttribute('role', 'dialog');
    windowDiv.setAttribute('aria-hidden', 'true');
    windowDiv.setAttribute('tabindex', '0');
    const setStatus = (text: string) => {
      statusEl.textContent = text;
    };
    const ensureAudioContext = async () => {
      if (!audioContext) {
        audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      if (audioContext.state === 'suspended') {
        try { await audioContext.resume(); } catch {}
      }
    };
    const resetAnalyser = () => {
      analyser = null;
      analyserBuffer = null;
    };
    const attachAnalyser = (node: AudioNode, connectToDestination: boolean) => {
      if (!audioContext) return;
      if (analyser) {
        try { analyser.disconnect(); } catch {}
      }
      try { node.disconnect(); } catch {}
      analyser = audioContext.createAnalyser();
      analyser.fftSize = 1024;
      analyser.smoothingTimeConstant = 0.0;
      analyserBuffer = new Float32Array(analyser.fftSize);
      node.connect(analyser);
      if (connectToDestination) {
        node.connect(audioContext.destination);
      }
    };
    const getCurrentModel = () => {
      const appDelegate = LAppDelegate.getInstance();
      const subs = appDelegate.getSubdelegates();
      if (!subs || subs.getSize() === 0) return null;
      const sub = subs.at(0);
      if (!sub) return null;
      const manager = sub.getLive2DManager();
      if (!manager) return null;
      return manager.getCurrentModel();
    };
    const resolveTargets = () => {
      targetParams = [];
      const currentModel = getCurrentModel();
      if (!currentModel) {
        targetsEl.textContent = 'no model';
        return;
      }
      const model = currentModel.getModel();
      if (!model || typeof model.getParameterCount !== 'function') {
        targetsEl.textContent = 'model unavailable';
        return;
      }
      const count = model.getParameterCount();
      const candidates: Array<{ id: string; min: number; max: number; score: number }> = [];
      for (let i = 0; i < count; i++) {
        const idObj = model.getParameterId(i);
        const id =
          (idObj?.getString?.().s as string | undefined) ??
          (idObj as unknown as string) ??
          `Param_${i}`;
        const min = model.getParameterMinimumValue(i) ?? 0;
        const max = model.getParameterMaximumValue(i) ?? 1;
        const lower = id.toLowerCase();
        let score = 0;
        if (lower.includes('parammouthopeny') || lower.includes('mouthopeny')) score = 3;
        else if (lower.includes('parammouthopen') || lower.includes('mouthopen')) score = 2;
        else if (lower.includes('parammouth') || lower.includes('mouth')) score = 1;
        if (score > 0) {
          candidates.push({ id, min, max, score });
        }
      }
      if (candidates.length === 0) {
        targetsEl.textContent = 'none';
        return;
      }
      candidates.sort((a, b) => b.score - a.score);
      const bestScore = candidates[0].score;
      targetParams = candidates.filter(c => c.score === bestScore);
      if (targetParams.length > 3) {
        targetParams = targetParams.slice(0, 3);
      }
      targetsEl.textContent = targetParams.map(t => t.id).join(', ');
    };
    const clearTargetOverrides = () => {
      if (!targetParams.length) return;
      const currentModel = getCurrentModel();
      if (!currentModel) return;
      targetParams.forEach((t) => {
        try {
          if (typeof (currentModel as any).clearParameterOverride === 'function') {
            (currentModel as any).clearParameterOverride(t.id);
          }
        } catch {}
      });
    };
    const updateMeter = (value: number) => {
      const pct = Math.max(0, Math.min(1, value)) * 100;
      meterFill.style.width = `${pct.toFixed(1)}%`;
    };
    const applyLipValue = (value: number) => {
      if (!targetParams.length) resolveTargets();
      const currentModel = getCurrentModel();
      if (!currentModel || targetParams.length === 0) return;
      targetParams.forEach((t) => {
        const v = t.min + value * (t.max - t.min);
        try {
          if (typeof (currentModel as any).queueParameterChange === 'function') {
            (currentModel as any).queueParameterChange(t.id, v);
          }
        } catch {}
      });
    };
    const updateLoop = () => {
      if (!enabled || !analyser || !analyserBuffer) {
        if (rafId) cancelAnimationFrame(rafId);
        rafId = null;
        updateMeter(0);
        return;
      }
      let rms = 0;
      if ((analyser as any).getFloatTimeDomainData) {
        analyser.getFloatTimeDomainData(analyserBuffer as any);
        for (let i = 0; i < analyserBuffer.length; i++) {
          const v = analyserBuffer[i];
          rms += v * v;
        }
        rms = Math.sqrt(rms / analyserBuffer.length);
      } else {
        const byteData = new Uint8Array(analyser.fftSize);
        analyser.getByteTimeDomainData(byteData);
        for (let i = 0; i < byteData.length; i++) {
          const v = (byteData[i] - 128) / 128;
          rms += v * v;
        }
        rms = Math.sqrt(rms / byteData.length);
      }
      const sensitivity = parseFloat(sensitivitySlider.value) || 1;
      const smoothing = parseFloat(smoothingSlider.value) || 0;
      const gate = parseFloat(gateSlider.value) || 0;
      let value = Math.max(0, (rms - gate) * sensitivity);
      value = Math.min(1, value);
      value = Math.pow(value, 0.6);
      smoothed = smoothed + (value - smoothed) * (1 - smoothing);
      applyLipValue(smoothed);
      updateMeter(smoothed);
      rafId = requestAnimationFrame(updateLoop);
    };
    const setEnabled = (next: boolean) => {
      enabled = next;
      enableCheckbox.checked = enabled;
      if (!enabled) {
        setStatus('Disabled');
        clearTargetOverrides();
        updateMeter(0);
      } else {
        resolveTargets();
        setStatus('Active');
        if (!rafId) rafId = requestAnimationFrame(updateLoop);
      }
    };
    const stopMic = () => {
      if (micStream) {
        micStream.getTracks().forEach(t => t.stop());
        micStream = null;
      }
      if (micSource) {
        try { micSource.disconnect(); } catch {}
        micSource = null;
      }
      micStatus.textContent = 'Not started';
      micBtn.textContent = 'Start Mic';
    };
    const startMic = async () => {
      try {
        await ensureAudioContext();
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        micStream = stream;
        if (!audioContext) return;
        micSource = audioContext.createMediaStreamSource(stream);
        attachAnalyser(micSource, false);
        micStatus.textContent = 'Live';
        micBtn.textContent = 'Stop Mic';
        if (enabled && !rafId) rafId = requestAnimationFrame(updateLoop);
      } catch (e) {
        console.warn('[LipSync] Mic start failed:', e);
        micStatus.textContent = 'Permission denied';
      }
    };
    const stopFile = () => {
      if (!fileAudio) return;
      fileAudio.pause();
      fileAudio.currentTime = 0;
      filePlayBtn.textContent = 'Play';
      fileStopBtn.disabled = true;
    };
    const playFile = async () => {
      if (!fileAudio) return;
      await ensureAudioContext();
      if (!audioContext) return;
      if (!fileSource) {
        try {
          fileSource = audioContext.createMediaElementSource(fileAudio);
          attachAnalyser(fileSource, true);
        } catch (e) {
          console.warn('[LipSync] MediaElementSource failed:', e);
        }
      }
      try {
        await fileAudio.play();
        filePlayBtn.textContent = 'Pause';
        fileStopBtn.disabled = false;
        if (enabled && !rafId) rafId = requestAnimationFrame(updateLoop);
      } catch (e) {
        console.warn('[LipSync] Audio play failed:', e);
      }
    };
    const pauseFile = () => {
      if (!fileAudio) return;
      fileAudio.pause();
      filePlayBtn.textContent = 'Play';
    };
    const setSource = (src: LipSyncSource) => {
      currentSource = src;
      micControls.style.display = src === 'mic' ? 'flex' : 'none';
      fileControls.style.display = src === 'file' ? 'flex' : 'none';
      if (src === 'mic') {
        stopFile();
        if (fileAudio) fileAudio.currentTime = 0;
        if (fileSource) {
          try { fileSource.disconnect(); } catch {}
        }
      } else {
        stopMic();
        if (micSource) {
          try { micSource.disconnect(); } catch {}
        }
      }
      resetAnalyser();
      updateMeter(0);
    };
    toggleBtn.addEventListener('click', () => {
      isWindowVisible = !isWindowVisible;
      windowDiv.style.display = isWindowVisible ? 'block' : 'none';
      toggleBtn.setAttribute('aria-expanded', String(isWindowVisible));
      windowDiv.setAttribute('aria-hidden', String(!isWindowVisible));
      updateDockedWindowsPositions();
      if (isWindowVisible) {
        const focusTarget = windowDiv.querySelector('input, button') as HTMLElement | null;
        if (focusTarget) focusTarget.focus();
      } else {
        toggleBtn.focus();
      }
    });
    enableCheckbox.addEventListener('change', () => setEnabled(enableCheckbox.checked));
    disableBtn.addEventListener('click', () => setEnabled(false));
    refreshBtn.addEventListener('click', () => resolveTargets());
    sourceMic.addEventListener('change', () => setSource('mic'));
    sourceFile.addEventListener('change', () => setSource('file'));
    micBtn.addEventListener('click', () => {
      if (micStream) stopMic();
      else startMic();
    });
    fileInput.addEventListener('change', () => {
      const files = fileInput.files;
      if (!files || files.length === 0) return;
      const file = files[0];
      if (fileUrl) URL.revokeObjectURL(fileUrl);
      fileUrl = URL.createObjectURL(file);
      if (!fileAudio) fileAudio = new Audio();
      fileAudio.src = fileUrl;
      fileAudio.load();
      fileNameEl.textContent = file.name;
      filePlayBtn.disabled = false;
      fileStopBtn.disabled = true;
      filePlayBtn.textContent = 'Play';
    });
    filePlayBtn.addEventListener('click', () => {
      if (!fileAudio) return;
      if (fileAudio.paused) playFile();
      else pauseFile();
    });
    fileStopBtn.addEventListener('click', () => stopFile());
    fileAudio?.addEventListener('ended', () => {
      filePlayBtn.textContent = 'Play';
      fileStopBtn.disabled = true;
    });
    sensitivitySlider.addEventListener('input', () => {
      const val = parseFloat(sensitivitySlider.value);
      sensitivityVal.textContent = `${val.toFixed(2)}x`;
    });
    smoothingSlider.addEventListener('input', () => {
      const val = parseFloat(smoothingSlider.value);
      smoothingVal.textContent = val.toFixed(2);
    });
    gateSlider.addEventListener('input', () => {
      const val = parseFloat(gateSlider.value);
      gateVal.textContent = val.toFixed(3);
    });
    const interactiveEls: HTMLElement[] = [
      toggleBtn, enableCheckbox, sourceMic, sourceFile, micBtn, fileInput,
      filePlayBtn, fileStopBtn, sensitivitySlider, smoothingSlider, gateSlider,
      refreshBtn, disableBtn
    ];
    interactiveEls.forEach((el) => {
      el.addEventListener('pointerdown', () => setUIElementActive(true), { passive: true });
      el.addEventListener('pointerup', () => setUIElementActive(false), { passive: true });
      el.addEventListener('pointerleave', () => setUIElementActive(false), { passive: true });
      el.addEventListener('touchstart', () => setUIElementActive(true), { passive: true });
      el.addEventListener('touchend', () => setUIElementActive(false), { passive: true });
    });
    setSource('mic');
    setEnabled(false);
    resolveTargets();
    (window as any).updateLipSyncTargets = resolveTargets;
  }