import { LAppDelegate } from "../delegation/delegate";
import { setUIElementActive } from "./state";
import { resetMergeSelection } from "./motionlist";

export function setupWorkspaceUI(): void {
    const select = document.getElementById('workspace-select') as HTMLSelectElement | null;
    const removeBtn = document.getElementById('workspace-remove-btn') as HTMLButtonElement | null;
    if (!select) {
        console.warn('Workspace select element not found in HTML.');
        return;
    }
    const refresh = (): void => {
        const appDelegate = LAppDelegate.getInstance();
        const subdelegates = appDelegate.getSubdelegates();
        if (!subdelegates || subdelegates.getSize() === 0) {
            select.innerHTML = '';
            select.disabled = true;
            return;
        }
        const firstSubdelegate = subdelegates.at(0);
        if (!firstSubdelegate) {
            select.innerHTML = '';
            select.disabled = true;
            return;
        }
        const manager = firstSubdelegate.getLive2DManager();
        if (!manager) {
            select.innerHTML = '';
            select.disabled = true;
            if (removeBtn) removeBtn.disabled = true;
            return;
        }
        const count = manager.getWorkspaceCount();
        select.innerHTML = '';
        if (count === 0) {
            const opt = document.createElement('option');
            opt.textContent = 'No model loaded';
            opt.value = '-1';
            select.appendChild(opt);
            select.disabled = true;
            if (removeBtn) removeBtn.disabled = true;
            return;
        }
        const currentIndex = manager.getCurrentSceneIndex();
        for (let i = 0; i < count; i++) {
            const opt = document.createElement('option');
            opt.value = String(i);
            opt.textContent = manager.getWorkspaceLabel(i);
            if (i === currentIndex) {
                opt.selected = true;
            }
            select.appendChild(opt);
        }
        select.disabled = count <= 1;
        if (removeBtn) removeBtn.disabled = count === 0;
    };
    select.addEventListener('change', () => {
        const value = select.value;
        const index = parseInt(value, 10);
        if (Number.isNaN(index) || index < 0) {
            return;
        }
        const appDelegate = LAppDelegate.getInstance();
        const subdelegates = appDelegate.getSubdelegates();
        if (!subdelegates || subdelegates.getSize() === 0) {
            return;
        }
        const firstSubdelegate = subdelegates.at(0);
        if (!firstSubdelegate) {
            return;
        }
        const manager = firstSubdelegate.getLive2DManager();
        if (!manager) {
            return;
        }
        if (typeof (manager as any).setActiveWorkspace === 'function') {
            (manager as any).setActiveWorkspace(index);
        }
    });
    if (removeBtn) {
        removeBtn.addEventListener('click', () => {
            const value = select.value;
            const index = parseInt(value, 10);
            if (Number.isNaN(index) || index < 0) {
                alert('No model selected to remove.');
                return;
            }
            const appDelegate = LAppDelegate.getInstance();
            const subdelegates = appDelegate.getSubdelegates();
            if (!subdelegates || subdelegates.getSize() === 0) return;
            const firstSubdelegate = subdelegates.at(0);
            if (!firstSubdelegate) return;
            const manager = firstSubdelegate.getLive2DManager();
            if (!manager) return;
            const removed = (manager as any).removeModelAt
                ? (manager as any).removeModelAt(index)
                : false;
            if (!removed) {
                alert('Failed to remove the selected model.');
                return;
            }
            refresh();
            if ((window as any).updatePartsList) (window as any).updatePartsList();
            if ((window as any).updateExpressionList)
                (window as any).updateExpressionList();
            resetMergeSelection();
        });
    }
    const stopProp = (ev: Event) => {
        ev.stopPropagation();
        setUIElementActive(true);
    };
    const stopPropEnd = (ev: Event) => {
        ev.stopPropagation();
        setTimeout(() => setUIElementActive(false), 100);
    };
    select.addEventListener('pointerdown', stopProp, { passive: true });
    select.addEventListener('pointerup', stopPropEnd, { passive: true });
    select.addEventListener('click', stopProp);
    select.addEventListener('touchstart', stopProp, { passive: true });
    select.addEventListener('touchend', stopPropEnd, { passive: true });
    select.addEventListener('mousedown', stopProp);
    select.addEventListener('mouseup', stopPropEnd);
    if (removeBtn) {
        removeBtn.addEventListener('pointerdown', stopProp, { passive: true });
        removeBtn.addEventListener('pointerup', stopPropEnd, { passive: true });
        removeBtn.addEventListener('click', stopProp);
        removeBtn.addEventListener('touchstart', stopProp, { passive: true });
        removeBtn.addEventListener('touchend', stopPropEnd, { passive: true });
        removeBtn.addEventListener('mousedown', stopProp);
        removeBtn.addEventListener('mouseup', stopPropEnd);
    }
    (window as any).updateWorkspaceList = refresh;
    refresh();
}