import { LAppDelegate } from "../delegation/delegate";

export function setupHitAreaOverlayUI(): void {
    const toggleBtn = document.getElementById('toggle-hitareas-btn') as HTMLButtonElement | null;
  
    if (!toggleBtn) {
      console.error('[HitAreas] Toggle button not found');
      return;
    }
  
    const existingOverlay = document.getElementById('hitareas-overlay');
    if (existingOverlay) existingOverlay.remove();
  
  const overlay = document.createElement('canvas') as HTMLCanvasElement;
    overlay.id = 'hitareas-overlay';
    overlay.style.cssText = `
      position: fixed !important;
      left: 0 !important;
      top: 0 !important;
      width: 100vw !important;
      height: 100vh !important;
      pointer-events: none !important;
      display: none !important;
      z-index: 99999999 !important;
    `;
  
    document.body.appendChild(overlay);
  
  let enabled = false;
  let rafId: number | null = null;
  let hitAreaBounds: Map<string, { minX: number, maxX: number, minY: number, maxY: number }> | null = null;
  let lastModelRef: any = null;

  let drawCanvas: HTMLCanvasElement = overlay;
  let ctx: CanvasRenderingContext2D | null = drawCanvas.getContext('2d');

  if (!ctx) {
    console.warn('[HitAreas] Initial 2D context failed on overlay, creating replacement canvas...');
    const fallback = document.createElement('canvas') as HTMLCanvasElement;
    fallback.id = 'hitareas-overlay';
    document.body.appendChild(fallback);
    drawCanvas = fallback;
    ctx = drawCanvas.getContext('2d');
    if (!ctx) {
      console.error('[HitAreas] Could not obtain 2D context at all, disabling hit-area overlay.');
      return;
    }
  }
  
    const getPrimarySubdelegate = () => {
      const appDelegate = LAppDelegate.getInstance();
      const subs = appDelegate.getSubdelegates();
      return subs?.at(0);
    };
  
    const getCurrentModel = () => {
      const sub = getPrimarySubdelegate();
      return sub?.getLive2DManager()?.getCurrentModel();
    };
  
    const getIdString = (id: any): string => {
      if (typeof id === 'string') return id;
      if (id?.getString?.().s) return id.getString().s;
      if (id?._id?.s) return id._id.s;
      if (id?.s) return id.s;
      return String(id || '');
    };
  
    const calculateBoundsFromDrawables = () => {
      const currentModel = getCurrentModel();
      if (!currentModel) return null;

      if (currentModel === lastModelRef && hitAreaBounds) {
        return hitAreaBounds;
      }
  
      const model = currentModel.getModel?.();
      const modelSetting = (currentModel as any)._modelSetting ||
        ((currentModel as any).getModelSetting?.());
  
      if (!model || !modelSetting) return null;
  
      const hitCount = modelSetting.getHitAreasCount?.() ?? modelSetting.getHitAreaCount?.() ?? 0;
      if (hitCount === 0) {
        return null;
      }
      let coreModel: any = model;
      if (!(coreModel as any).drawables) {
        if ((model as any)._model && (model as any)._model.drawables) {
          coreModel = (model as any)._model;
        } else if ((model as any)._ptr && (model as any)._ptr.drawables) {
          coreModel = (model as any)._ptr;
        }
      }
  
      const drawables = (coreModel as any)?.drawables;
  
      if (!drawables) {
        console.error('[HitAreas] No drawables object found');
        return null;
      }
  
      
  
      const drawableIds = drawables.ids as string[];
      const drawableVertexCounts = drawables.vertexCounts as Int32Array;
      const drawableVertexPositions = drawables.vertexPositions as Float32Array[];
  
      if (!drawableIds || !drawableVertexCounts || !drawableVertexPositions) {
        console.error('[HitAreas] Missing drawable data');
        return null;
      }
  
      const bounds = new Map<string, { minX: number, maxX: number, minY: number, maxY: number }>();
  
      for (let h = 0; h < hitCount; h++) {
        const hitName = modelSetting.getHitAreaName?.(h) ?? `HitArea_${h}`;
        const hitId = modelSetting.getHitAreaId?.(h);
        const hitIdString = getIdString(hitId);
        let drawableIndex = -1;
        for (let i = 0; i < drawableIds.length; i++) {
          if (drawableIds[i] === hitIdString) {
            drawableIndex = i;
            break;
          }
        }
  
        if (drawableIndex < 0) {
          console.warn(`[HitAreas] No drawable found for ${hitName} (${hitIdString})`);
          console.warn(`  Available drawable IDs (first 10):`, drawableIds.slice(0, 10));
          continue;
        }
        const vCount = drawableVertexCounts[drawableIndex];
        const verts = drawableVertexPositions[drawableIndex];
  
        if (!verts || vCount <= 0) {
          console.warn(`[HitAreas] No vertices for drawable ${drawableIndex}`);
          continue;
        }
        let minX = Infinity;
        let maxX = -Infinity;
        let minY = Infinity;
        let maxY = -Infinity;
  
        for (let v = 0; v < vCount; v++) {
          const x = verts[v * 2];
          const y = verts[v * 2 + 1];
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
        }
  
        bounds.set(hitIdString, { minX, maxX, minY, maxY });
      }
      lastModelRef = currentModel;
      hitAreaBounds = bounds;
      return bounds;
    };
  
    const draw = () => {
      if (!enabled) {
        rafId = null;
        return;
      }
      drawCanvas.style.position = 'fixed';
      drawCanvas.style.zIndex = '2147483647';
      drawCanvas.style.pointerEvents = 'none';
      drawCanvas.style.backgroundColor = 'transparent';
      const sub = getPrimarySubdelegate();
      const canvas = sub?.getCanvas?.() as HTMLCanvasElement | undefined;
  
      if (canvas) {
        const rect = canvas.getBoundingClientRect();
        drawCanvas.style.left = `${rect.left}px`;
        drawCanvas.style.top = `${rect.top}px`;
        drawCanvas.style.width = `${rect.width}px`;
        drawCanvas.style.height = `${rect.height}px`;
  
        if (drawCanvas.width !== canvas.width || drawCanvas.height !== canvas.height) {
          drawCanvas.width = canvas.width;
          drawCanvas.height = canvas.height;
        }
      }
  
      ctx!.clearRect(0, 0, drawCanvas.width, drawCanvas.height);
      hitAreaBounds = calculateBoundsFromDrawables();
  
      if (!hitAreaBounds) {
        rafId = requestAnimationFrame(draw);
        return;
      }
  
      const view = sub?.getView?.();
      if (!view) {
        rafId = requestAnimationFrame(draw);
        return;
      }
  
      const viewMatrix = (view as any)._viewMatrix;
      const deviceToScreen = (view as any)._deviceToScreen;
  
      const toScreen = (vx: number, vy: number) => {
        let mx = vx;
        let my = vy;
  
        const currentModel = getCurrentModel();
        const modelMatrix = (currentModel as any)?._modelMatrix;
  
        if (modelMatrix) {
          if (typeof modelMatrix.transformX === 'function') {
            mx = modelMatrix.transformX(vx);
          }
          if (typeof modelMatrix.transformY === 'function') {
            my = modelMatrix.transformY(vy);
          }
        }
  
        let sx = mx;
        let sy = my;
  
        if (viewMatrix) {
          if (typeof viewMatrix.transformX === 'function') {
            sx = viewMatrix.transformX(mx);
          }
          if (typeof viewMatrix.transformY === 'function') {
            sy = viewMatrix.transformY(my);
          }
        }
  
        let dx = sx;
        let dy = sy;
  
        if (deviceToScreen) {
          if (typeof deviceToScreen.invertTransformX === 'function') {
            dx = deviceToScreen.invertTransformX(sx);
          }
          if (typeof deviceToScreen.invertTransformY === 'function') {
            dy = deviceToScreen.invertTransformY(sy);
          }
        }
  
        return { x: dx, y: dy };
      };
  
      const colors = [
        { fill: 'rgba(255, 0, 255, 0.3)', stroke: 'rgba(255, 0, 255, 1.0)' },
        { fill: 'rgba(0, 255, 255, 0.3)', stroke: 'rgba(0, 255, 255, 1.0)' },
        { fill: 'rgba(255, 255, 0, 0.3)', stroke: 'rgba(255, 255, 0, 1.0)' },
        { fill: 'rgba(255, 128, 0, 0.3)', stroke: 'rgba(255, 128, 0, 1.0)' },
        { fill: 'rgba(128, 0, 255, 0.3)', stroke: 'rgba(128, 0, 255, 1.0)' }
      ];
  
      ctx.lineWidth = 3;
      ctx.font = 'bold 14px Arial';
  
      let idx = 0;
      hitAreaBounds.forEach((bounds, hitId) => {
        const p0 = toScreen(bounds.minX, bounds.minY);
        const p1 = toScreen(bounds.maxX, bounds.maxY);
  
        const left = Math.min(p0.x, p1.x);
        const top = Math.min(p0.y, p1.y);
        const width = Math.abs(p1.x - p0.x);
        const height = Math.abs(p1.y - p0.y);
  
        if (width > 1 && height > 1) {
          const color = colors[idx % colors.length];
  
          ctx.fillStyle = color.fill;
          ctx.fillRect(left, top, width, height);
  
          ctx.strokeStyle = color.stroke;
          ctx.strokeRect(left, top, width, height);
  
          const label = hitId.replace('HitArea_', '');
          ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
          const textWidth = ctx.measureText(label).width;
          ctx.fillRect(left, top - 22, textWidth + 10, 22);
  
          ctx.fillStyle = 'white';
          ctx.fillText(label, left + 5, top - 6);
        }
  
        idx++;
      });
  
      rafId = requestAnimationFrame(draw);
    };
  
    const setEnabled = (next: boolean) => {
      enabled = next;
      overlay.style.display = next ? 'block' : 'none';
  
      if (next) {
        hitAreaBounds = null;
        lastModelRef = null;
        if (!rafId) rafId = requestAnimationFrame(draw);
      } else {
        if (rafId) {
          cancelAnimationFrame(rafId);
          rafId = null;
        }
        hitAreaBounds = null;
        lastModelRef = null;
        ctx!.clearRect(0, 0, drawCanvas.width, drawCanvas.height);
      }
    };
  
    toggleBtn.addEventListener('click', () => setEnabled(!enabled));
  }
